INSERT INTO `xinxi` VALUES (1, '新版“移动端盘点”功能上线', '系统已更新微信小程序盘点插件，支持扫码后自动关联库位信息。相关操作手册已上传至企业网盘，欢迎查看并试用。', 0, '2026-03-30 23:28:50', '系统', '0');
INSERT INTO `xinxi` VALUES (2, '由于物流延迟导致的入库积压', '受近期强降雨影响，华东地区部分供应商配送延迟，预计本周内入库总量将比平时增长 30%，请收货组加强人力调配。', 0, '2026-03-30 23:29:05', '系统', '0');
INSERT INTO `xinxi` VALUES (3, '核心物料“轴承-A03”跌破安全值', '智能监控显示，核心零部件 A03 轴承当前库存仅余 50 件，已触发三级预警逻辑。请采购部立即联系供应商下单，避免生产线停工。', 1, '2026-03-30 23:37:48', '系统', '0');
